// Custom Cloudflare Worker entrypoint wrapping OpenNext + Cron Trigger auto-sync
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore Generated by @opennextjs/cloudflare at build time
import openNextHandler from "./.open-next/worker.js";
import { runScheduledSync } from "./src/lib/sync-engine";
import type { WorkerEnv } from "./src/lib/d1";

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore Generated Durable Object handlers
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

const worker = {
  async fetch(request: Request, env: WorkerEnv, ctx: ExecutionContext): Promise<Response> {
    return openNextHandler.fetch(request, env, ctx);
  },

  async scheduled(
    _event: ScheduledController,
    env: WorkerEnv,
    ctx: ExecutionContext
  ): Promise<void> {
    ctx.waitUntil(runScheduledSync(env.DB ?? null, "cron"));
  },
};

export default worker;
